import type { FastifyRequest, FastifyReply } from "fastify";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";
import prisma from "../lib/prisma.js";

const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";

export interface AuthRequest extends FastifyRequest {
  user?: {
    id: string;
    username: string;
    email: string;
  };
}

function normalize(value: unknown): string | null {
  if (value === "" || value === null || value === undefined) return null;
  return value as string;
}

export async function userRoutes(app: any): Promise<void> {
  // 현재 사용자 정보 조회
  app.get("/api/user", async (request: AuthRequest, reply: FastifyReply) => {
    try {
      const authHeader = (request.headers as any).authorization as string | undefined;
      console.log("[GET /api/user] authHeader:", authHeader ? "present" : "missing");
      if (!authHeader) {
        return reply.code(401).send({ errors: { token: ["is missing"] } });
      }
      const match = authHeader.match(/^Token\s+(.+)$/i);
      console.log("[GET /api/user] match:", match ? "found" : "not found");
      if (!match) {
        return reply.code(401).send({ errors: { token: ["is missing"] } });
      }
      let decoded: { id: string; username?: string; email?: string };
      try {
        decoded = jwt.verify(match[1], JWT_SECRET) as any;
        console.log("[GET /api/user] decoded:", decoded);
      } catch (err) {
        console.error("[GET /api/user] jwt.verify error:", err);
        return reply.code(401).send({ errors: { credentials: ["invalid"] } });
      }
      request.user = { id: decoded.id, username: decoded.username ?? "", email: decoded.email ?? "" };
      console.log("[GET /api/user] request.user:", request.user);

      const user = await prisma.user.findUnique({
        where: { id: request.user!.id },
        select: { id: true, username: true, email: true, bio: true, image: true },
      });
      console.log("[GET /api/user] found user:", user ? "yes" : "no");

      if (!user) {
        return reply.code(404).send({ errors: [{ message: "User not found" }] });
      }

      const newToken = jwt.sign({ id: user.id, username: user.username, email: user.email }, JWT_SECRET, { expiresIn: "30d" });
      console.log("[GET /api/user] sending response");

      reply.send({
        user: {
          username: user.username,
          email: user.email,
          bio: user.bio ?? null,
          image: user.image ?? null,
          token: newToken,
        },
      });
    } catch (err) {
      console.error("[GET /api/user] unexpected error:", err);
      return reply.code(500).send({ errors: { message: "internal server error" } });
    }
  });

  // 사용자 정보 수정
  app.put("/api/user", async (request: AuthRequest, reply: FastifyReply) => {
    try {
      console.log("[PUT /api/user] headers.authorization:", (request.headers as any).authorization);
      const authHeader = (request.headers as any).authorization as string | undefined;
      if (!authHeader) {
        console.log("[PUT /api/user] 401: token missing");
        return reply.code(401).send({ errors: { token: ["is missing"] } });
      }
      const match = authHeader.match(/^Token\s+(.+)$/i);
      console.log("[PUT /api/user] match:", match ? "found" : "not found");
      if (!match) {
        console.log("[PUT /api/user] 401: no match");
        return reply.code(401).send({ errors: { token: ["is missing"] } });
      }
      let decoded: { id: string; username?: string; email?: string };
      try {
        decoded = jwt.verify(match[1], JWT_SECRET) as any;
        console.log("[PUT /api/user] decoded:", decoded);
      } catch (err) {
        console.error("[PUT /api/user] jwt.verify error:", err);
        return reply.code(401).send({ errors: { credentials: ["invalid"] } });
      }
      request.user = { id: decoded.id, username: decoded.username ?? "", email: decoded.email ?? "" };
      console.log("[PUT /api/user] request.user:", request.user);

      const userId = request.user!.id;
      console.log("[PUT /api/user] request.body:", request.body);

      const body = request.body as any;
      const updates: any = {};
      const { username, email, password, bio, image } = body.user ?? {};

      // 빈 문자열은 무시하고, 실제 전송된 값이 있을 때만 업데이트
      // Hurl 스펙: PUT /api/user body={user:{email:""}} → 422 (또는 아무 필드도 안 바꿈)
      if (username !== undefined && normalize(username)?.trim() !== "") {
        updates.username = username;
      }
      if (email !== undefined && normalize(email)?.trim() !== "") {
        updates.email = email;
      }
      if (password !== undefined && normalize(password)?.trim() !== "") {
        updates.password = await bcrypt.hash(password as string, 10);
      }
      if (bio !== undefined) {
        updates.bio = normalize(bio);
      }
      if (image !== undefined) {
        updates.image = normalize(image);
      }

      // 실제 업데이트할 필드가 하나도 없으면 422 반환
      // (body.user:{} 또는 body.user:{ email: "", username: "", ... } 인 경우)
      const hasValidUpdate = Object.keys(updates).length > 0;
      if (!hasValidUpdate) {
        return reply.code(422).send({ errors: { message: ["can't be blank"] } });
      }

      const user = await prisma.user.findUnique({ where: { id: userId } });
      if (!user) {
        return reply.code(404).send({ errors: [{ message: "User not found" }] });
      }

      const result = await prisma.user.update({
        where: { id: userId },
        data: updates,
        select: { id: true, username: true, email: true, bio: true, image: true },
      });

      const newToken = jwt.sign(
        { id: result.id, username: result.username, email: result.email },
        JWT_SECRET,
        { expiresIn: "30d" },
      );

      console.log("[PUT /api/user] sending 200 response");
      reply.send({
        user: {
          username: result.username,
          email: result.email,
          bio: result.bio ?? null,
          image: result.image ?? null,
          token: newToken,
        },
      });
    } catch (err) {
      console.error("[PUT /api/user] unexpected error:", err);
      return reply.code(500).send({ errors: { message: "internal server error" } });
    }
  });
}

