458	    });
459	  });
460	
461	  // DELETE /api/articles/:slug - 아티클 삭제
462	  app.delete("/api/articles/:slug", async (request: any, reply) => {
463	    const slug = request.params.slug as string;
464	    const token = extractToken(request);
465	    if (!token) {
466	      return reply.code(401).send({ errors: { token: ["is missing"] } });
