import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";

export async function profilesRoutes(app: FastifyInstance): Promise<void> {
  // GET /api/profiles/:username - 프로필 조회
  app.get("/api/profiles/:username", async (request: FastifyRequest, reply: FastifyReply) => {
    const username = (request.params as any).username as string;
    const token = (request.headers as any).authorization as string | undefined;
    let currentUserId: string | null = null;

    if (token) {
      try {
        const match = token.match(/^Token\s+(.+)$/i);
        if (match) {
          const jwt = await import("jsonwebtoken");
          const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
          const decoded = jwt.verify(match[1], JWT_SECRET) as any;
          currentUserId = decoded.id;
        }
      } catch {
        // ignore
      }
    }

    const user = await prisma.user.findUnique({
      where: { username },
    });

    if (!user) {
      return reply.code(404).send({ errors: { profile: ["not found"] } });
    }

    let following = false;
    if (currentUserId && currentUserId !== user.id) {
      following = await prisma.follow.findUnique({
        where: {
          followerId_followingId: {
            followerId: currentUserId,
            followingId: user.id,
          },
        },
      }) !== null;
    }

    return reply.send({
      profile: {
        username: user.username,
        bio: user.bio ?? null,
        image: user.image ?? null,
        following,
      },
    });
  });

  // POST /api/profiles/:username/follow - 팔로우
  app.post("/api/profiles/:username/follow", async (request: FastifyRequest, reply: FastifyReply) => {
    const username = (request.params as any).username as string;
    const headers: any = request.headers;
    const authHeader = headers.authorization;

    let token: string | null = null;
    if (authHeader) {
      const match = authHeader.match(/^Token\s+(.+)$/i);
      if (match) token = match[1];
    }

    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const jwt = await import("jsonwebtoken");
    const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
    let currentUserId: string;
    try {
      const decoded = jwt.verify(token, JWT_SECRET) as any;
      currentUserId = decoded.id;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    const targetUser = await prisma.user.findUnique({
      where: { username },
    });

    if (!targetUser) {
      return reply.code(404).send({ errors: { profile: ["not found"] } });
    }

    if (currentUserId === targetUser.id) {
      return reply.code(409).send({ errors: { profile: ["can't follow yourself"] } });
    }

    await prisma.follow.upsert({
      where: {
        followerId_followingId: {
          followerId: currentUserId,
          followingId: targetUser.id,
        },
      },
      create: {
        followerId: currentUserId,
        followingId: targetUser.id,
      },
      update: {
        followerId: currentUserId,
        followingId: targetUser.id,
      },
    });

    return reply.send({
      profile: {
        username: targetUser.username,
        bio: targetUser.bio ?? null,
        image: targetUser.image ?? null,
        following: true,
      },
    });
  });

  // DELETE /api/profiles/:username/follow - 언팔로우
  app.delete("/api/profiles/:username/follow", async (request: FastifyRequest, reply: FastifyReply) => {
    const username = (request.params as any).username as string;
    const headers: any = request.headers;
    const authHeader = headers.authorization;

    let token: string | null = null;
    if (authHeader) {
      const match = authHeader.match(/^Token\s+(.+)$/i);
      if (match) token = match[1];
    }

    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }

    const jwt = await import("jsonwebtoken");
    const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";
    let currentUserId: string;
    try {
      const decoded = jwt.verify(token, JWT_SECRET) as any;
      currentUserId = decoded.id;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    const targetUser = await prisma.user.findUnique({
      where: { username },
    });

    if (!targetUser) {
      return reply.code(404).send({ errors: { profile: ["not found"] } });
    }

    await prisma.follow.deleteMany({
      where: {
        followerId: currentUserId,
        followingId: targetUser.id,
      },
    });

    return reply.send({
      profile: {
        username: targetUser.username,
        bio: targetUser.bio ?? null,
        image: targetUser.image ?? null,
        following: false,
      },
    });
  });
}

