import type { FastifyPluginAsync, FastifyRequest, FastifyReply } from "fastify";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";

// Hurl 스펙 에러 포맷: {"errors": {"field": ["message"]}}
function fieldError(field: string, message: string) {
  return { errors: { [field]: [message] } };
}

// Fastify 데코레이터에 attach할 인증 미들웨어
export const authenticate = async (request: any, reply: FastifyReply) => {
  const authHeader = request.headers.authorization;
  if (!authHeader) {
    reply.code(401).send({ errors: { token: ["is missing"] } });
    return;
  }
  const match = authHeader.match(/^Token\s+(.+)$/i);
  if (!match) {
    reply.code(401).send({ errors: { token: ["is missing"] } });
    return;
  }
  try {
    const decoded = jwt.verify(match[1], JWT_SECRET) as { id: string; username: string; email: string };
    request.user = decoded;
  } catch {
    reply.code(401).send({ errors: { credentials: ["invalid"] } });
  }
};

// Fastify 플러그인: authenticate 데코레이터 등록
export const authPlugin: FastifyPluginAsync = async (fastify) => {
  fastify.decorate("authenticate", authenticate);
};

// JWT 토큰 생성 헬퍼
export function generateToken(payload: { id: string; username: string; email: string }): string {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: "30d" });
}

// Hurl 호환형 일반 에러 응답 헬퍼
export function unauthorized(msg?: string) {
  return { errors: { credentials: ["invalid"] } };
}

